def transform(grid):
    """Restore the occluded cells of a framed, diagonal-cycle pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frame = grid[2][2]
    background = grid[0][0]

    # The colored interior repeats by diagonal r+c. Find the shortest period
    # whose residue classes explain the visible cells, tolerating the unusual
    # small motif at the upper-left corner of the interior.
    diagonals = [(r + c, grid[r][c]) for r in range(3, h) for c in range(3, w)
                 if grid[r][c] != 0]
    best = None
    for period in range(2, 11):
        votes = defaultdict(Counter)
        for diagonal, color in diagonals:
            votes[diagonal % period][color] += 1
        score = sum(max(v.values()) for v in votes.values()) / len(diagonals)
        if best is None or score > best[0] + 1e-12:
            best = (score, period, votes)
    best_score = best[0]
    # Larger multiples can fit a few extra outliers; prefer the shortest
    # period essentially as accurate as the best one.
    eligible = []
    for period in range(2, 11):
        votes = defaultdict(Counter)
        for diagonal, color in diagonals:
            votes[diagonal % period][color] += 1
        score = sum(max(v.values()) for v in votes.values()) / len(diagonals)
        if score >= best_score - 0.01:
            eligible.append((period, votes))
    period, votes = min(eligible, key=lambda item: item[0])
    cycle = {residue: counts.most_common(1)[0][0]
             for residue, counts in votes.items()}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = background
            elif r == 2 or c == 2:
                out[r][c] = frame
            else:
                out[r][c] = cycle[(r + c) % period]
    return out
