def transform(grid):
    """Restore zeros in the framed pattern of colors repeating by diagonal."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = grid[0][0]
    frame = grid[2][2]

    samples = [(r + c, grid[r][c]) for r in range(3, h) for c in range(3, w)
