    for period in range(2, 13):
        votes = defaultdict(Counter)
        for diagonal, color in samples:
            votes[diagonal % period][color] += 1
        score = sum(max(counts.values()) for counts in votes.values()) / len(samples)
        fits.append((score, period, votes))
    best_score = max(item[0] for item in fits)
    score, period, votes = min((item for item in fits if item[0] >= best_score - 0.015),
                               key=lambda item: item[1])
    color_by_residue = {residue: counts.most_common(1)[0][0]
                        for residue, counts in votes.items()}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
